on conflict (id) do update set
  name=excluded.name, bn=excluded.bn, zone=excluded.zone,
  lat=excluded.lat, lng=excluded.lng, area=excluded.area,
  open_time=excluded.open_time, close_time=excluded.close_time,
  crowd=excluded.crowd, peak_start=excluded.peak_start, peak_end=excluded.peak_end,
  est=excluded.est, tags=excluded.tags, theme=excluded.theme,
  description=excluded.description, nearest_metro=excluded.nearest_metro,
  is_published=true, updated_at=now();

on conflict (id) do update set
  type=excluded.type, name=excluded.name, lat=excluded.lat, lng=excluded.lng,
  area=excluded.area, open_time=excluded.open_time, close_time=excluded.close_time,
  note=excluded.note, is_published=true;

on conflict (id) do update set
  name=excluded.name, route=excluded.route, color=excluded.color,
  first_train=excluded.first_train, last_train=excluded.last_train,
  note=excluded.note, position=excluded.position,
  is_published=true, updated_at=now();

on conflict (id) do update set
  line_id=excluded.line_id, name=excluded.name, bn=excluded.bn,
  lat=excluded.lat, lng=excluded.lng, interchange=excluded.interchange,
  position=excluded.position, is_published=true, updated_at=now();