insert into public.pandals
 (id,name,bn,zone,lat,lng,area,open_time,close_time,crowd,peak_start,peak_end,est,tags,theme,description,nearest_metro,is_published)
values
('bagbazar','Bagbazar Sarbojanin','বাগবাজার সর্বজনীন','north',22.6009,88.3661,'Bagbazar Ghat, North Kolkata','06:00','23:59','high',17,23,1919,ARRAY['heritage','family']::text[],'Classic ekchala sabeki protima','One of the oldest community pujas of the city. Famous for its traditional single-frame idol, the Bagbazar mela around it, and a crowd that stays gentle enough for families and elders.','Shobhabazar Sutanuti',true),
('kumartuli-park','Kumartuli Park Sarbojanin','কুমোরটুলি পার্ক','north',22.6035,88.3606,'Kumartuli, North Kolkata','08:00','23:59','high',18,23,1996,ARRAY['award','bigbudget']::text[],'Art installation puja','Sits right beside the idol-makers colony. Regularly wins art awards, so pair it with a daytime walk through Kumartuli lanes to watch the clay idols being finished.','Shobhabazar Sutanuti',true),
('ahiritola','Ahiritola Sarbojanin','আহিরীটোলা সর্বজনীন','north',22.5936,88.3563,'Ahiritola Ghat, North Kolkata','08:00','23:30','medium',18,22,1919,ARRAY['heritage','award']::text[],'Riverside heritage theme','A century-old puja by the Ganga. Quieter than its neighbours in the afternoon and a favourite of photographers for the ghat light.','Shobhabazar Sutanuti',true),
('sovabazar-rajbari','Sovabazar Rajbari','শোভাবাজার রাজবাড়ি','north',22.5955,88.3625,'Sovabazar, North Kolkata','09:00','21:00','medium',16,21,1757,ARRAY['heritage','bonedi']::text[],'Bonedi bari puja (household puja)','The grand old family puja of the Deb dynasty. Not a street pandal — a courtyard puja inside a heritage mansion. Best visited in daylight, and dress respectfully.','Shobhabazar Sutanuti',true),
('jagat-mukherjee','Jagat Mukherjee Park','জগৎ মুখার্জি পার্ক','north',22.6085,88.3745,'Shyambazar, North Kolkata','09:00','23:30','high',18,23,1938,ARRAY['award','bigbudget']::text[],'Large themed installation','Big north-Kolkata name a short walk from Shyambazar five-point crossing. Very heavy footfall from Saptami evening onward.','Shyambazar',true),
('hatibagan','Hatibagan Sarbojanin','হাতিবাগান সর্বজনীন','north',22.598,88.37,'Hatibagan, North Kolkata','08:00','23:59','high',18,23,1935,ARRAY['heritage']::text[],'Traditional with a modern twist','Right in the middle of the Hatibagan shopping district. Combine with street food along Bidhan Sarani.','Shyambazar',true),
('nalin-sarkar','Nalin Sarkar Street Sarbojanin','নলিন সরকার স্ট্রিট','north',22.5967,88.3719,'Hatibagan, North Kolkata','09:00','23:30','medium',19,23,1934,ARRAY['award']::text[],'Narrative art puja','Compact lane puja known for tight, well-crafted concepts rather than scale. Usually manageable even at peak hours.','Shyambazar',true),
('tala-prattoy','Tala Prattoy','টালা প্রত্যয়','north',22.6162,88.3777,'Tala, North Kolkata','10:00','23:30','high',18,23,1990,ARRAY['award','bigbudget']::text[],'Conceptual art puja','One of the most consistently talked-about art pujas of the north. Expect long, slow-moving queues on Ashtami and Nabami.','Belgachia',true),
('chaltabagan','Chaltabagan Lohapatty','চালতাবাগান লোহাপট্টি','north',22.5878,88.3702,'Manicktala, North Kolkata','09:00','23:30','medium',19,23,1946,ARRAY['heritage']::text[],'Traditional grandeur','Near Manicktala crossing. Good stop while moving between north and central Kolkata clusters.','Girish Park',true),
('md-ali-park','Mohammad Ali Park','মহম্মদ আলি পার্ক','central',22.5772,88.3576,'Central Avenue, Kolkata','09:00','23:59','high',18,23,1969,ARRAY['bigbudget']::text[],'Replica architecture','Famous for large replicas of monuments. Sits right on Central Avenue, so it is one of the easiest big pandals to reach by metro.','Central',true),
('college-square','College Square','কলেজ স্কোয়ার','central',22.5757,88.3639,'College Street, Kolkata','09:00','23:59','extreme',18,24,1948,ARRAY['bigbudget','family']::text[],'Lit-up water body + monument replica','The lighting over the swimming pool is the real attraction — the reflection in the water is the shot everyone comes for. Extremely crowded after 7pm.','Central',true),
('santosh-mitra','Santosh Mitra Square','সন্তোষ মিত্র স্কোয়ার','central',22.5661,88.3702,'Sealdah, Kolkata','09:00','23:59','extreme',17,24,1936,ARRAY['bigbudget']::text[],'Blockbuster set-piece puja','Known for enormous, headline-grabbing sets. Enter from the Sealdah side and be ready for a long queue — go before 5pm if you can.','Sealdah',true),
('sealdah-railway','Sealdah Railway Athletic Club','শিয়ালদহ রেলওয়ে','central',22.5688,88.3722,'Sealdah, Kolkata','09:00','23:30','medium',18,23,1965,'{}'::text[],'Community puja','A calmer alternative right next to Sealdah station, useful if you are arriving by train and want one quick pandal.','Sealdah',true),
('ekdalia','Ekdalia Evergreen Club','একডালিয়া এভারগ্রিন','south',22.5218,88.3705,'Gariahat, South Kolkata','09:00','23:59','extreme',18,24,1943,ARRAY['bigbudget','family']::text[],'Temple replica with heavy chandelier work','One of the "big four" of south Kolkata. Grand temple replicas and imported chandeliers. Walkable from Singhi Park and Ballygunge Cultural.','Kalighat',true),
('singhi-park','Singhi Park Sarbojanin','সিংহি পার্ক','south',22.5192,88.3661,'Gariahat, South Kolkata','09:00','23:59','high',18,24,1941,ARRAY['bigbudget','family']::text[],'Traditional lighting spectacle','Right beside Ekdalia — most people do these two back to back. Beautiful chandelier and lighting work.','Kalighat',true),
('ballygunge-cultural','Ballygunge Cultural Association','বালিগঞ্জ কালচারাল','south',22.5245,88.3639,'Ballygunge, South Kolkata','09:00','23:59','high',18,24,1952,ARRAY['award','bigbudget']::text[],'Art-forward concept puja','Consistently one of the best-designed pujas in the south. Third stop of the classic Gariahat triangle.','Kalighat',true),
('deshapriya-park','Deshapriya Park','দেশপ্রিয় পার্ক','south',22.5182,88.3527,'Rashbehari, South Kolkata','09:00','23:59','extreme',17,24,1938,ARRAY['bigbudget']::text[],'Giant idol / open-ground puja','Huge open-ground puja famous for oversized idols. Because it is an open park, the crowd moves faster than in lane pandals.','Kalighat',true),
('suruchi-sangha','New Alipore Suruchi Sangha','নিউ আলিপুর সুরুচি সংঘ','south',22.5024,88.3364,'New Alipore, South Kolkata','09:00','23:59','high',18,23,1953,ARRAY['award','bigbudget']::text[],'A different Indian state every year','Builds its pandal around the folk art of one Indian state each year — always a crafts-heavy, colourful experience.','Majerhat',true),
('chetla-agrani','Chetla Agrani Club','চেতলা অগ্রণী','south',22.5117,88.3376,'Chetla, South Kolkata','09:00','23:59','high',18,23,1993,ARRAY['award']::text[],'Designer art puja','Designed year after year by well-known art directors. Very close to Kalighat temple, so combine the two.','Kalighat',true),
('badamtala','Badamtala Ashar Sangha','বাদামতলা আষাঢ় সংঘ','south',22.5152,88.3438,'Kalighat, South Kolkata','09:00','23:59','high',18,23,1939,ARRAY['award']::text[],'Concept-driven installation','Award regular in the Kalighat cluster. Narrow approach lane, so entry can be slow at night.','Kalighat',true),
('tridhara','Tridhara Sammilani','ত্রিধারা সম্মিলনী','south',22.5169,88.3549,'Deshapriya Park, South Kolkata','09:00','23:59','high',18,24,1947,ARRAY['award','bigbudget']::text[],'Large-scale art concept','A minute from Deshapriya Park. One of the strongest art pujas of the Rashbehari belt.','Kalighat',true),
('mudiali','Mudiali Club','মুদিয়ালি ক্লাব','south',22.5108,88.3494,'Rabindra Sarobar, South Kolkata','09:00','23:59','high',18,23,1935,ARRAY['award','family']::text[],'Craft and detail work','Old, reliable, beautifully finished. Right next to Rabindra Sarobar metro, which makes it an easy first or last stop.','Rabindra Sarobar',true),
('shibmandir','Shibmandir Sarbojanin','শিবমন্দির সর্বজনীন','south',22.5147,88.3597,'Rashbehari, South Kolkata','09:00','23:59','high',18,23,1948,ARRAY['award']::text[],'Detail-rich art puja','Part of the Rashbehari cluster you can finish on foot: Shibmandir → Tridhara → Deshapriya Park → Badamtala.','Kalighat',true),
('sixtysix-pally','66 Pally','৬৬ পল্লী','south',22.5104,88.3457,'Kalighat, South Kolkata','09:00','23:59','medium',19,23,1936,ARRAY['award']::text[],'Experimental art','Smaller footprint, strong ideas. Good breather between the two mega pandals nearby.','Kalighat',true),
('naktala-udayan','Naktala Udayan Sangha','নাকতলা উদয়ন সংঘ','south',22.4796,88.3719,'Naktala, South Kolkata','09:00','23:59','high',18,23,1947,ARRAY['award','bigbudget']::text[],'Emotive storytelling puja','A far-south favourite with a big reputation for storytelling and music design. Reachable from the Garia end of the Blue Line.','Masterda Surya Sen',true),
('jodhpur-park','Jodhpur Park Sarbojanin','যোধপুর পার্ক','south',22.4998,88.3652,'Jodhpur Park, South Kolkata','09:00','23:59','medium',18,23,1949,ARRAY['family']::text[],'Neighbourhood grandeur','Calm, well-organised, family-friendly. A good place to rest between the Gariahat and Garia clusters.','Mahanayak Uttam Kumar',true),
('kankurgachi','Kankurgachi Yubak Brinda','কাঁকুড়গাছি যুবক বৃন্দ','east',22.5787,88.3893,'Kankurgachi, East Kolkata','09:00','23:30','medium',18,23,1937,ARRAY['heritage']::text[],'Traditional community puja','Steps from Phoolbagan metro. Easy add-on when you are travelling on the Green Line.','Phoolbagan',true),
('beleghata-33','Beleghata 33 Pally','বেলেঘাটা ৩৩ পল্লী','east',22.562,88.3966,'Beleghata, East Kolkata','09:00','23:30','medium',19,23,1945,ARRAY['award']::text[],'Concept installation','The heart of the Beleghata cluster — several pujas within a 10 minute walk of each other.','Beleghata',true),
('kestopur-prafulla','Kestopur Prafulla Kanan','কেষ্টপুর প্রফুল্ল কানন','east',22.5975,88.4327,'Kestopur, East Kolkata','09:00','23:30','medium',18,23,1978,'{}'::text[],'Large themed pandal','Convenient if you are staying near the airport or Rajarhat side of the city.','Salt Lake Sector V',true),
('ultadanga-sanghasree','Ultadanga Sanghasree','উল্টোডাঙা সংঘশ্রী','east',22.5936,88.3925,'Ultadanga, East Kolkata','09:00','23:30','medium',18,23,1954,ARRAY['award']::text[],'Art puja','Sits between the north and Salt Lake clusters — a natural stop when crossing over.','Phoolbagan',true),
('sreebhumi','Sreebhumi Sporting Club','শ্রীভূমি স্পোর্টিং ক্লাব','saltlake',22.6091,88.4022,'Lake Town, Kolkata','09:00','23:59','extreme',17,24,1973,ARRAY['bigbudget','family']::text[],'Giant replica of a world landmark','The single most crowded pandal of the season most years. Traffic on VIP Road backs up badly — go early morning or on Chaturthi/Panchami.','Dum Dum',true),
('dumdum-park-bharat','Dumdum Park Bharat Chakra','দমদম পার্ক ভারত চক্র','saltlake',22.6072,88.4127,'Dum Dum Park, Kolkata','09:00','23:59','high',18,23,1967,ARRAY['award']::text[],'Socially themed art puja','Dum Dum Park has four or five strong pujas within walking distance — this is the anchor of that cluster.','Dum Dum',true),
('dumdum-tarun-sangha','Dumdum Park Tarun Sangha','দমদম পার্ক তরুণ সংঘ','saltlake',22.606,88.4145,'Dum Dum Park, Kolkata','09:00','23:59','high',18,23,1975,ARRAY['award']::text[],'Immersive installation','Walk here straight from Bharat Chakra — about four minutes on foot.','Dum Dum',true),
('fd-block','FD Block Salt Lake','এফ.ডি ব্লক সল্টলেক','saltlake',22.5905,88.4165,'Salt Lake Sector 3','09:00','23:59','high',18,23,1978,ARRAY['bigbudget','family']::text[],'Big-set block puja','The best-known of the Salt Lake block pujas. Wide roads and organised queues make it comfortable for families.','City Centre',true),
('ak-block','AK Block Salt Lake','এ.কে ব্লক সল্টলেক','saltlake',22.5836,88.411,'Salt Lake Sector 2','09:00','23:30','medium',18,23,1981,ARRAY['family']::text[],'Neighbourhood themed puja','Relaxed, tidy, and easy to reach on the Green Line. Good with kids or elderly visitors.','Bengal Chemical',true),
('bj-block','BJ Block Salt Lake','বি.জে ব্লক সল্টলেক','saltlake',22.5866,88.4198,'Salt Lake Sector 2','09:00','23:30','medium',18,23,1979,ARRAY['family']::text[],'Craft-led block puja','Part of the Salt Lake block circuit — FD, BJ, AK and IB are all doable on foot in one evening.','City Centre',true),
('behala-nutandal','Behala Nutan Dal','বেহালা নূতন দল','west',22.4938,88.3126,'Behala, South-West Kolkata','09:00','23:59','high',18,23,1949,ARRAY['award']::text[],'Art-driven concept','Behala has become one of the strongest art-puja belts in the city, and this is one of its leading names.','Behala Bazar',true),
('barisha-club','Barisha Club','বড়িশা ক্লাব','west',22.4826,88.3095,'Barisha, Behala','09:00','23:59','high',18,23,1958,ARRAY['award']::text[],'Socially conscious storytelling','Known for emotionally charged concepts that get talked about nationally. Reachable on the Purple Line.','Sakherbazar',true),
('sahapur-sarbojanin','Sahapur Sarbojanin','সাহাপুর সর্বজনীন','west',22.499,88.3182,'Sahapur, Behala','09:00','23:30','medium',19,23,1961,'{}'::text[],'Community puja','A good, less-crowded stop while doing the Behala circuit.','Behala Bazar',true),
('shibpur-mandirtala','Shibpur Mandirtala Sarbojanin','শিবপুর মন্দিরতলা','howrah',22.5698,88.3212,'Shibpur, Howrah','09:00','23:30','medium',18,23,1952,'{}'::text[],'Traditional Howrah puja','Easy to reach now that the Green Line runs to Howrah Maidan. Pair it with a Howrah bridge walk.','Howrah Maidan',true),
('bally-kalitala','Bally Kalitala Sarbojanin','বালি কালীতলা','howrah',22.6432,88.3405,'Bally, Howrah','09:00','23:30','medium',18,23,1948,'{}'::text[],'Neighbourhood puja','North Howrah option, best combined with a Belur Math visit in the daytime.','Belur (rail)',true),
('santragachi-club','Santragachi Sarbojanin','সাঁতরাগাছি সর্বজনীন','howrah',22.5828,88.283,'Santragachi, Howrah','09:00','23:30','medium',18,23,1963,'{}'::text[],'Large community pandal','Handy if you are arriving into Santragachi station.','Santragachi (rail)',true),
('kalyani-iti','Kalyani ITI More Sarbojanin','কল্যাণী আই.টি.আই মোড়','kalyani',22.975,88.4345,'ITI More, Kalyani','09:00','23:30','high',18,23,1975,ARRAY['bigbudget']::text[],'Big-set township puja','Kalyani has grown into a serious puja destination — the ITI More cluster draws visitors from all over Nadia.','Kalyani (rail)',true),
('kalyani-a9','Kalyani A-9 Square','কল্যাণী এ-৯ স্কোয়ার','kalyani',22.9805,88.4292,'A Block, Kalyani','09:00','23:30','medium',18,23,1982,'{}'::text[],'Township block puja','Wide roads and organised crowd management — comfortable for an evening walk-through.','Kalyani (rail)',true),
('kalyani-luxmi','Kalyani Luxmi Narayan Colony','কল্যাণী লক্ষ্মীনারায়ণ কলোনি','kalyani',22.9689,88.4408,'Kalyani, Nadia','09:00','23:00','low',19,23,1988,ARRAY['family']::text[],'Community puja','Small, warm neighbourhood puja. Low crowd, good for a quiet visit.','Kalyani (rail)',true)
